package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var a, b, c, l int
	fmt.Fscanf(reader, "%d %d %d %d", &a, &b, &c, &l)

	// Sort the sticks
	sticks := []int{a, b, c}
	sort.Ints(sticks)
	x, y, z := sticks[0], sticks[1], sticks[2]

	// We need to count the number of non-negative integers (da, db, dc)
	// such that da + db + dc <= l
	// and (x+da, y+db, z+dc) can form a non-degenerate triangle.
	// Since x <= y <= z, the triangle inequality that matters is:
	// (x+da) + (y+db) > (z+dc)
	// i.e., x + y + da + db > z + dc
	// da + db - dc > z - x - y
	// Let k = z - x - y. We need da + db - dc > k.
	// Note: the other two inequalities are automatically satisfied since x <= y <= z and all increases are non-negative.
	// (y+db) + (z+dc) > (x+da) is always true since y >= x and z >= x, and db, dc >= 0.
	// (x+da) + (z+dc) > (y+db) is always true since z >= y and x >= 0, da, dc >= 0.

	// So the condition is: da + db + dc <= l AND da + db - dc > k
	// where k = z - x - y.

	// Let's iterate over possible values of dc (increase of the longest stick).
	// dc can range from 0 to l.
	// For a fixed dc, we need da + db <= l - dc AND da + db > k + dc.
	// Let rem = l - dc. We need da + db <= rem AND da + db > k + dc.
	// Let s = da + db. We need k + dc < s <= rem.
	// So s must be in the range [max(0, k+dc+1), rem].
	// The number of non-negative integer pairs (da, db) with da + db = s is s + 1.
	// So for a fixed dc, the number of valid (da, db) pairs is:
	// sum_{s = max(0, k+dc+1)}^{rem} (s + 1)
	// if max(0, k+dc+1) <= rem, else 0.

	// Let low = max(0, k+dc+1)
	// Let high = rem
	// If low > high, contribution is 0.
	// Otherwise, sum_{s=low}^{high} (s+1) = sum_{s=low}^{high} s + (high - low + 1)
	// sum_{s=low}^{high} s = (low + high) * (high - low + 1) / 2
	// So total = (low + high) * (high - low + 1) / 2 + (high - low + 1)
	// = (high - low + 1) * (low + high + 2) / 2

	// We need to be careful with integer overflow. a, b, c, l up to 3e5.
	// l is at most 3e5, so rem is at most 3e5.
	// low and high are at most 3e5.
	// (high - low + 1) is at most 3e5 + 1.
	// (low + high + 2) is at most 6e5 + 2.
	// Product is at most ~1.8e11, which fits in int64 but not int32.
	// We'll use int64 for the computation.

	var total int64 = 0
	k := z - x - y

	for dc := 0; dc <= l; dc++ {
		rem := l - dc
		if rem < 0 {
			break
		}
		low := k + dc + 1
		if low < 0 {
			low = 0
		}
		high := rem
		if low > high {
			continue
		}
		// Number of pairs = sum_{s=low}^{high} (s+1)
		// = (high - low + 1) * (low + high + 2) / 2
		n := high - low + 1
		sum := int64(n) * int64(low+high+2) / 2
		total += sum
	}

	fmt.Println(total)
}
