	reader := bufio.NewReader(os.Stdin)
	var a, b, c, l int
	fmt.Fscanf(reader, "%d %d %d %d", &a, &b, &c, &l)

	sticks := []int{a, b, c}
	sort.Ints(sticks)
	a, b, c = sticks[0], sticks[1], sticks[2]

	// We need to count the number of triples (da, db, dc) such that:
	// da, db, dc >= 0
	// da + db + dc <= l
	// and (a+da, b+db, c+dc) can form a non-degenerate triangle.
	// Since a <= b <= c, the triangle inequality reduces to:
	// (a+da) + (b+db) > (c+dc)
	// i.e., a + b + da + db > c + dc
	// i.e., da + db - dc > c - a - b
	// Let k = c - a - b. We need da + db - dc > k.
	// Note: k can be negative, zero, or positive.

	// Total number of non-negative integer solutions to da + db + dc <= l is C(l+3, 3).
	// We need to subtract those where (a+da) + (b+db) <= (c+dc), i.e., da + db - dc <= k.

	// Let's count the number of (da, db, dc) with da+db+dc <= l and da+db-dc <= k.
	// Let s = da + db + dc. Then s <= l.
	// da + db - dc <= k  =>  da + db - (s - da - db) <= k  =>  2(da+db) - s <= k  =>  da+db <= (s+k)/2.
	// For a fixed s, the number of (da, db, dc) with da+db+dc = s and da+db <= floor((s+k)/2) is:
	// Let t = da + db. Then dc = s - t. We need t <= floor((s+k)/2) and t >= 0, dc >= 0 => t <= s.
	// Also da, db >= 0, so for a given t, the number of (da, db) with da+db = t is t+1.
	// So for fixed s, the count is sum_{t=0}^{min(s, floor((s+k)/2))} (t+1).
	// But we also need s <= l and s >= 0.

	// Alternatively, we can iterate over s from 0 to l, and for each s, compute the number of valid (da, db, dc) with da+db+dc = s and da+db <= floor((s+k)/2).
	// Then sum over s.

	// But l can be up to 3e5, so iterating over s from 0 to l is acceptable.

	// Let's define a function to compute the number of non-negative integer solutions to x + y + z = s with x + y <= M, where M = floor((s+k)/2).
	// If M < 0, then count = 0.
	// If M >= s, then count = number of non-negative solutions to x+y+z=s = C(s+2, 2) = (s+1)(s+2)/2.
	// Otherwise, 0 <= M < s:
	//   count = sum_{t=0}^{M} (t+1) = (M+1)(M+2)/2.

	// Wait, let me re-derive:
	// For fixed s, we have x + y + z = s, x,y,z >= 0.
	// We require x + y <= M.
	// Let t = x + y. Then z = s - t. We need 0 <= t <= s and t <= M.
	// For each t, the number of (x,y) with x+y=t is t+1.
	// So total = sum_{t=0}^{min(M, s)} (t+1).
	// If M >= s, then sum_{t=0}^{s} (t+1) = (s+1)(s+2)/2.
	// If M < s, then sum_{t=0}^{M} (t+1) = (M+1)(M+2)/2.
	// If M < 0, then 0.

	// So for each s in [0, l]:
	//   M = floor((s + k) / 2)
	//   if M < 0: count_s = 0
	//   else if M >= s: count_s = (s+1)*(s+2)/2
	//   else: count_s = (M+1)*(M+2)/2

	// Then the number of invalid triples is sum_{s=0}^{l} count_s.
	// The answer is total - invalid, where total = C(l+3, 3) = (l+1)(l+2)(l+3)/6.

	// But note: k = c - a - b.

	// Let's compute.

	total := int64(0)
	// total = (l+1)*(l+2)*(l+3)/6
	total = int64(l+1) * int64(l+2) * int64(l+3) / 6

	k := c - a - b

	invalid := int64(0)
	for s := 0; s <= l; s++ {
		// M = floor((s + k) / 2)
		// Since s+k can be negative, we need to be careful with integer division.
		// In Go, integer division truncates towards zero. But we want floor division.
		// For negative numbers, floor((s+k)/2) is not the same as (s+k)/2 in Go if s+k is negative and odd.
		// Example: s+k = -1, floor(-1/2) = -1, but in Go, -1/2 = 0 (truncation towards zero).
		// So we need to compute floor((s+k)/2) correctly.

		num := s + k
		var M int
		if num >= 0 {
			M = num / 2
		} else {
			// floor(num/2) for negative num
			// If num is even, num/2 is exact. If odd, we need to subtract 1.
			if num%2 == 0 {
				M = num / 2
			} else {
				M = num/2 - 1
			}
		}

		if M < 0 {
			// count_s = 0
			continue
		} else if M >= s {
			invalid += int64(s+1) * int64(s+2) / 2
		} else {
			invalid += int64(M+1) * int64(M+2) / 2
		}
	}

	answer := total - invalid
	fmt.Println(answer)
}
